  import cylinderStl from './assets/cylinder.stl?raw';
  import mixedStl from './assets/mixed.stl?raw';
  import chamferedStl from './assets/m4_chamfered_cylinder.stl?raw';
  import roundedStl from './assets/m5_toroidal_fillet.stl?raw';
  import twoCubes from './assets/two-cubes';
  import type { Options, Result, DocumentPreview, BodyResult } from './lib/types';
  const initial: Options = { input_unit:'mm', weld_tolerance_mm:0.000001, plane_tolerance_mm:0.000001, reconstruction:'planar', cylinder_fit_tolerance_mm:0.00001, max_deviation_mm:0.05 };
  let options = $state<Options>({ ...initial });
  const positiveOr = (value: unknown, fallback: number): number => typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback;
  function serializableOptions(value: Options): Options {
