  }
  try { const saved = JSON.parse(localStorage.getItem('fabstep.options.v1') || 'null'); if (saved && ['mm','inch'].includes(saved.input_unit)) options = serializableOptions({ ...initial, ...saved, reconstruction: ['planar','cylinders','primitives','surfaces'].includes(saved.reconstruction) ? saved.reconstruction : 'planar' }); } catch { /* stockage optionnel */ }
  let bytes = $state<Uint8Array | null>(null), name = $state(''), result = $state<Result | null>(null), preview = $state<DocumentPreview | null>(null);
  let errorState = $state<{ kind: 'key'; key: Key } | { kind: 'native'; value: unknown } | null>(null);
  const error = $derived.by(() => { void i18n.locale; return errorState ? (errorState.kind === 'key' ? t(errorState.key) : errorText(errorState.value)) : ''; });
  let format = $state<'stl'|'3mf'>('stl'), selectedId = $state('');
  function initialCommit(): Options { return { ...options }; }
  let committed: Options = initialCommit();
  let showHelp = $state(false);
  let noteKey = $state<Key | null>(null);
  let recognitionFailed = $state(false);
  let busy = $state(false), dragging = $state(false), showEdges = $state(true), fitSignal = $state(0);
  // Le verrou du moteur peut appartenir à une ancienne requête ; l’indicateur suit la demande courante.
  let processing = $state<{ requestId:number; phase:'queued'|'preview'|'converting'; startedAt:number } | null>(null);
  let input: HTMLInputElement; let current = $state(Date.now() * 1000); let fileToken = 0, queued = false, timer: ReturnType<typeof setTimeout>; let history: Options[] = [], future: Options[] = [];
  let sourceId: number | null = null, uploadedSourceId: number | null = null;
  type Internals = SourceBridge;
  const native = () => (window as unknown as { __TAURI_INTERNALS__?: Internals }).__TAURI_INTERNALS__;
  const engineKeys: Record<string, Key> = { 'threemf.invalid_archive':'engine.m3_invalid_archive', 'threemf.archive_limit':'engine.m3_archive_limit', 'threemf.unsupported_compression':'engine.m3_unsupported_compression', 'threemf.invalid_path':'engine.m3_invalid_path', 'threemf.duplicate_part':'engine.m3_duplicate_part', 'threemf.missing_part':'engine.m3_missing_part', 'threemf.invalid_xml':'engine.m3_invalid_xml', 'threemf.xml_limit':'engine.m3_xml_limit', 'threemf.invalid_package':'engine.m3_invalid_package', 'threemf.external_resource':'engine.m3_external_resource', 'threemf.invalid_transform':'engine.m3_invalid_transform', 'threemf.non_finite':'engine.m3_non_finite', 'threemf.complexity_limit':'engine.m3_complexity_limit', 'threemf.invalid_reference':'engine.m3_invalid_reference', 'threemf.invalid_index':'engine.m3_invalid_index', 'threemf.empty_model':'engine.m3_empty_model', 'threemf.unsupported_version':'engine.m3_unsupported_version', 'threemf.unsupported_extension':'engine.m3_unsupported_extension', 'threemf.invalid_unit':'engine.m3_invalid_unit', 'threemf.duplicate_id':'engine.m3_duplicate_id', 'threemf.unsupported_object':'engine.m3_unsupported_object', 'mesh.invalid_index':'engine.m3_mesh_invalid_index', 'input.too_many_bodies':'engine.m3_too_many_bodies', 'cad.bodies_not_separated':'workspace.notSeparated', 'engine.source_metadata':'engine.source_metadata', 'engine.source_transport':'engine.source_transport', 'engine.source_busy':'engine.source_busy', 'engine.source_conflict':'engine.source_conflict', 'engine.source_allocation':'engine.source_allocation', 'engine.stale':'engine.engine_stale', 'engine.state':'engine.engine_state', 'io.extension':'engine.io_extension', 'io.file':'engine.io_file', 'io.path':'engine.io_path', 'engine.task':'engine.engine_task', 'validation.analytic_mismatch':'engine.validation_analytic_mismatch', 'recognition.conic_unproven':'engine.recognition_conic_unproven', 'recognition.partial_unproven':'engine.recognition_partial_unproven', 'validation.distance_budget':'engine.distance_budget', 'validation.distance_resolution':'engine.distance_resolution', 'recognition.disabled':'engine.recognition_disabled', 'recognition.unsupported':'engine.recognition_unsupported', 'recognition.too_complex':'engine.recognition_too_complex', 'recognition.invalid_analysis':'engine.recognition_invalid_analysis', "options.invalid_tolerance": "engine.options_invalid_tolerance", "mesh.empty": "engine.mesh_empty", "mesh.non_finite": "engine.mesh_non_finite", "mesh.invalid_volume": "engine.mesh_invalid_volume", "mesh.coordinate_range": "engine.mesh_coordinate_range", "mesh.degenerate_triangle": "engine.mesh_degenerate_triangle", "mesh.duplicate_triangle": "engine.mesh_duplicate_triangle", "mesh.non_manifold_edge": "engine.mesh_non_manifold_edge", "mesh.open": "engine.mesh_open", "mesh.inconsistent_orientation": "engine.mesh_inconsistent_orientation", "mesh.multiple_components": "engine.mesh_multiple_components", "mesh.non_manifold_vertex": "engine.mesh_non_manifold_vertex", "input.too_large": "engine.input_too_large", "input.too_many_triangles": "engine.input_too_many_triangles", "stl.invalid_length": "engine.stl_invalid_length", "stl.invalid_ascii": "engine.stl_invalid_ascii", "planar.too_complex": "engine.planar_too_complex", "planar.invalid_contour": "engine.planar_invalid_contour", "validation.bounds_mismatch": "engine.validation_bounds_mismatch", "validation.volume_mismatch": "engine.validation_volume_mismatch" };
  const diagnosticKeys: Record<string, Key> = { 'recognition.rounded_box_intent_assumed':'engine.rounded_box_intent_assumed', 'recognition.rounded_box_coverage':'engine.rounded_box_coverage', 'recognition.rounded_intent_assumed':'engine.rounded_intent_assumed', 'recognition.conic_intent_assumed':'engine.conic_intent_assumed', 'precision.custom_tolerances':'engine.custom_tolerances', 'document.product_names_adapted':'engine.product_names_adapted', 'threemf.metadata_ignored':'engine.m3_metadata_ignored', 'document.separate_bodies':'workspace.bodiesSeparated', 'recognition.circular_intent_assumed':'engine.recognition_circular_intent', 'recognition.bound_scope':'engine.recognition_bound_scope', "validation.native_required": "engine.diag_validation_native_required", "mesh.orientation_reversed": "engine.diag_mesh_orientation_reversed", "planar.approximate": "engine.diag_planar_approximate" };
  function errorText(e: unknown): string {
    if (typeof e !== 'object' || !e || !('message' in e)) return `${t('engine.unknownDetail')}: ${String(e)}`;
    const raw = e as { code?: string; message: string; body?: { id: string; name: string; detail: string } | null };
    const context = errorContext(raw, t('workspace.stlBody'), id => {
      const body = preview?.bodies.find(body => body.id === id || id.startsWith(`${body.id}/component/`));
      return body ? bodyText(body) : undefined;
    });
    const err = { ...raw, message: context.detail };
    const withBody = (text: string) => context.prefix + text;
    if (err.code === 'recognition.surface_unproven') return withBody(`${t('engine.recognition_surface_unproven')} (${err.code}) — ${t('engine.unknownDetail')}: ${err.message}`);
    if (err.code === 'recognition.conic_unproven') return withBody(`${t('engine.recognition_conic_unproven')} (${err.code}) — ${t('engine.unknownDetail')}: ${err.message}`);
    if (err.code === 'cad.invalid_model' && err.message === "Le contour d'une face dépasse la tolérance de planéité du noyau.") return withBody(`${t('engine.cad_contour_planarity')} (${err.code})`);
    if (err.code === 'recognition.deviation_exceeded') {
      const values = [...err.message.matchAll(/([+-]?\d+(?:\.\d+)?(?:e[+-]?\d+)?)\s*mm/gi)].map(m => m[1]);
      if (values.length >= 2) return withBody(`${t('engine.recognition_deviation', { bound:values[0], budget:values[1] })} (${err.code})`);
    }
    if (err.code === 'validation.distance_exceeded') {
      const value = err.message.match(/([+-]?\d+(?:\.\d+)?(?:e[+-]?\d+)?)\s*mm/i)?.[1];
      if (value) return withBody(`${t('engine.distance_exceeded', { limit:value })} (${err.code})`);
    }
    const detailed: Record<string, Key> = { 'validation.distance_invalid_mesh':'engine.distance_invalid_mesh', 'cad.tessellation_failed':'engine.tessellation_failed', 'cad.tessellation_too_complex':'engine.tessellation_too_complex' };
    if (err.code && detailed[err.code]) return withBody(`${t(detailed[err.code])} (${err.code}) — ${t('engine.unknownDetail')}: ${err.message}`);
    if (err.code === 'cad.bodies_not_separated') return withBody(`${t('workspace.notSeparated')} — ${t('engine.unknownDetail')}: ${err.message} (${err.code})`);
    const key = err.code && engineKeys[err.code];
    if (key && err.code && (err.code.startsWith('threemf.') || err.code === 'mesh.invalid_index' || err.code === 'input.too_many_bodies')) return withBody(`${t(key)} (${err.code}) — ${t('engine.unknownDetail')}: ${err.message}`);
    return withBody((key ? t(key) : `${t('engine.unknownDetail')}: ${err.message}`) + (err.code ? ` (${err.code})` : ''));
  }
  function invalidate(preservePreview = false) {
    current++;
    if (native()) void native()!.invoke<void>('invalidate_result', { requestId: current, sourceId }).catch(() => {});
    result = null; if (!preservePreview) { preview = null; selectedId = ''; } errorState = null; noteKey = null; recognitionFailed = false;
    clearTimeout(timer); queued = false; processing = null;
    if (!validPreferences(options)) {
      errorState = { kind:'key', key:'workspace.invalid' }; return;
    }
    if (!bytes || !native()) return;
    processing = { requestId:current, phase:'queued', startedAt:performance.now() };
    const id = current;
    timer = setTimeout(() => { if (id === current) { queued = true; void run(); } }, 250);
  }
  async function run() {
    if (busy || !queued || !bytes || sourceId === null || !native()) return;
    queued = false; busy = true;
    const id = current, source = bytes, key = sourceId, bridge = native()!, opts = serializableOptions(options), requestedFormat = format;
    if (processing?.requestId === id) processing.phase = 'preview';
    let previewComplete = false;
    try {
      if (uploadedSourceId !== key) {
        await uploadSource(bridge, source, key, requestedFormat);
        if (sourceId === key) uploadedSourceId = key;
      }
      if (id !== current || sourceId !== key) return;
      const doc = await bridge.invoke<DocumentPreview>('preview_document', { requestId:id, sourceId:key, options:opts });
      if (id !== current || doc.request_id !== id) return;
      preview = doc; previewComplete = true;
      if (processing?.requestId === id) processing.phase = 'converting';
      const converted = await bridge.invoke<Result>('convert_document', { requestId:id, sourceId:key, options:opts });
      if (id === current && converted.request_id === id) { selectedId = ''; result = converted; }
    } catch (e) {
      if (id === current) { errorState = { kind:'native', value:e }; recognitionFailed = previewComplete && opts.reconstruction !== 'planar' && typeof e === 'object' && e !== null && 'code' in e && String(e.code).startsWith('recognition.'); }
    } finally {
      if (processing?.requestId === id) processing = null;
      busy = false;
      if (queued) void run();
    }
  }
  function commitOptions() {
    const previous = commitSnapshot(options, committed); if (!previous) return;
    history.push(previous); if (history.length > 50) history.shift();
    future = []; committed = { ...options }; saveOptions();
  }
  function change(patch: Partial<Options>) {
    const unitChanged = patch.input_unit !== undefined && patch.input_unit !== options.input_unit;
    options = { ...options, ...patch }; commitOptions(); invalidate(!unitChanged);
  }
  function editNumber(patch: Partial<Options>) { options = { ...options, ...patch }; invalidate(true); }
  function finishNumber(e: FocusEvent | KeyboardEvent) {
    if (e instanceof KeyboardEvent) { if (e.key !== 'Enter') return; e.preventDefault(); (e.currentTarget as HTMLInputElement).blur(); return; }
    commitOptions();
  }
  function saveOptions() { if (!validPreferences(committed)) return; try { localStorage.setItem('fabstep.options.v1', JSON.stringify(committed)); } catch { /* optionnel */ } }
  function undo(redo = false) {
    if (!sameOptions(options, committed)) { const unitChanged = options.input_unit !== committed.input_unit; options = { ...committed }; invalidate(!unitChanged); return; }
    const from = redo ? future : history, to = redo ? history : future;
    const prev = from.pop(); if (prev) { const unitChanged = prev.input_unit !== options.input_unit; to.push({ ...committed }); committed = { ...prev }; options = { ...prev }; saveOptions(); invalidate(!unitChanged); }
  }
  async function load(file: File) {
    const token = ++fileToken; bytes = null; sourceId = null; uploadedSourceId = null; name = file.name; invalidate();
    if (!/\.(stl|3mf)$/i.test(file.name)) { errorState = { kind:'key', key:'workspace.formatHint' }; return; }
    format = /\.3mf$/i.test(file.name) ? '3mf' : 'stl';
    if (file.size > 64 * 1024 * 1024) { errorState = { kind:'key', key:'workspace.tooLarge' }; return; }
    try { const data = new Uint8Array(await file.arrayBuffer()); if (token !== fileToken) return; setSource(data); fitSignal++; }
    catch { if (token === fileToken) errorState = { kind:'key', key:'workspace.errorFile' }; }
  }
  function setSource(data: Uint8Array) { bytes = data; sourceId = current + 1; uploadedSourceId = null; invalidate(); }
  function example() { fileToken++; format='stl'; options = { ...options, input_unit:'mm', reconstruction:'planar' }; commitOptions(); const v = [[0,0,0],[20,0,0],[20,20,0],[0,20,0],[0,0,20],[20,0,20],[20,20,20],[0,20,20]]; const faces = [[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]]; const stl = 'solid cube\n' + faces.map(f => `facet normal 0 0 0\n outer loop\n${f.map(i => `  vertex ${v[i].join(' ')}`).join('\n')}\n endloop\nendfacet\n`).join('') + 'endsolid cube\n'; name = 'cube.stl'; setSource(new TextEncoder().encode(stl)); fitSignal++; }
  function cylinderExample() { fileToken++; format='stl'; options = { ...options, input_unit:'mm', reconstruction:'cylinders' }; commitOptions(); name = 'cylinder.stl'; setSource(new TextEncoder().encode(cylinderStl)); fitSignal++; }
  function mixedExample() { fileToken++; format='stl'; options = { ...options, input_unit:'mm', reconstruction:'cylinders' }; commitOptions(); name = 'mixed.stl'; setSource(new TextEncoder().encode(mixedStl)); fitSignal++; }
  function chamferedExample() { fileToken++; format='stl'; options = { ...options, input_unit:'mm', reconstruction:'primitives' }; commitOptions(); name = 'm4_chamfered_cylinder.stl'; setSource(new TextEncoder().encode(chamferedStl)); fitSignal++; }
  function roundedExample() { fileToken++; format='stl'; options = { ...options, input_unit:'mm', reconstruction:'surfaces' }; commitOptions(); name = 'm5_toroidal_fillet.stl'; setSource(new TextEncoder().encode(roundedStl)); fitSignal++; }
  function twoCubesExample() { fileToken++; name='two-cubes.3mf'; format='3mf'; options={...options, reconstruction:'planar'}; commitOptions(); setSource(twoCubes.slice()); fitSignal++; }
  async function exportStep() { if (!result || result.request_id !== current || !native()) return; const id = current; try { const path = await native()!.invoke<string | null>('export_step', { requestId:id, suggestedName: name.replace(/\.(stl|3mf)$/i, '') + '.step' }); if (id === current) noteKey = path ? 'workspace.saved' : 'workspace.cancelled'; } catch (e) { if (id === current) errorState = { kind:'native', value:e }; } }
  const diagnosticText = (code: string, fallback: string, body: BodyResult | null = selection) => { if (code === 'recognition.rounded_coverage' && body?.rounded_recognition) return t('engine.rounded_coverage', { spheres:body.rounded_recognition.report.spheres, tori:body.rounded_recognition.report.tori, cylinders:body.rounded_recognition.report.cylinders, cones:body.rounded_recognition.report.cones, planes:body.rounded_recognition.model.revolved.mixed.planes.length }); if (code === 'recognition.revolved_coverage' && body?.revolved_recognition) return t('engine.revolved_coverage', { cones:body.revolved_recognition.report.cones, cylinders:body.revolved_recognition.report.cylinders, planes:body.revolved_recognition.model.mixed.planes.length }); if (code === 'recognition.mixed_coverage' && body?.mixed_recognition) return t('engine.mixed_coverage', { cylinders:body.mixed_recognition.report.cylinders, planes:body.mixed_recognition.model.planes.length }); if (code === 'mesh.vertices_moved') { const distance = fallback.match(/([+-]?\d+(?:\.\d+)?(?:e[+-]?\d+)?)\s*mm/i)?.[1]; if (distance) return t('engine.verticesMoved', { distance }); } return diagnosticKeys[code] ? t(diagnosticKeys[code]) : `${t('engine.unknownDetail')}: ${fallback}`; };
  const fmt = (n: number) => new Intl.NumberFormat(i18n.locale === 'fr' ? 'fr-FR' : 'en-GB', { maximumFractionDigits:6 }).format(n);
  const selectedBody = $derived(result?.bodies.find(body => body.id === selectedId) ?? null);
  const selectedPreview = $derived(preview?.bodies.find(body => body.id === selectedId) ?? null);
  const selection = $derived(selectedBody ?? (selectedId ? null : result?.bodies.length === 1 ? result.bodies[0] : null));
  const report = $derived(selection?.recognition?.report ?? selection?.mixed_recognition?.report ?? selection?.revolved_recognition?.report ?? selection?.rounded_recognition?.report ?? selection?.rounded_box_recognition?.report ?? null);
  const metrics = $derived(selection?.cad ?? result?.cad ?? null);
  const sourceTriangles = $derived(selection ? selection.analysis.report.input_triangles : result ? result.bodies.reduce((sum, body) => sum + body.analysis.report.input_triangles, 0) : selectedPreview ? selectedPreview.mesh.triangles.length : preview?.bodies.reduce((sum, body) => sum + body.mesh.triangles.length, 0) ?? null);
  const sourceVertices = $derived(selection ? selection.analysis.report.vertices : result ? result.bodies.reduce((sum, body) => sum + body.analysis.report.vertices, 0) : selectedPreview ? selectedPreview.mesh.vertices.length : preview?.bodies.reduce((sum, body) => sum + body.mesh.vertices.length, 0) ?? null);
  const unitNames: Record<string, Key> = { millimeter:'workspace.unitMillimeter', mm:'workspace.unitMillimeter', micron:'workspace.unitMicron', centimeter:'workspace.unitCentimeter', inch:'workspace.unitInch', foot:'workspace.unitFoot', meter:'workspace.unitMeter' };
  const unitText = (unit: string) => unitNames[unit] ? t(unitNames[unit]) : unit;
  const bodyText = (body: { id:string; name:string; provenance?: import('./lib/types').BodyProvenance }) => bodyLabel(body, t('workspace.stlBody'), (object, instance) => t('workspace.objectBody', { object, instance }));
  const precise = (n: number) => new Intl.NumberFormat(i18n.locale === 'fr' ? 'fr-FR' : 'en-GB', { maximumSignificantDigits: 6 }).format(n);
  const settingValue = (n: number) => i18n.locale === 'fr' ? String(n).replace('.', ',') : String(n);
  const measuredValue = (n: number) => settingValue(Number(n.toPrecision(6)));
  const dims = $derived(metrics ? metrics.bounds_mm[1].map((v,i) => fmt(v - metrics!.bounds_mm[0][i])).join(' × ') : '—');
  function key(e: KeyboardEvent) { if (showHelp) return; if (e.key === '?' && !['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) { e.preventDefault(); showHelp = true; return; } const editing = ['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement)?.tagName); if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'o') { e.preventDefault(); input.click(); } else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && !editing) { e.preventDefault(); undo(e.shiftKey); } else if (!editing && e.key.toLowerCase() === 'f') fitSignal++; }
  onMount(() => { window.addEventListener('keydown', key); return () => { window.removeEventListener('keydown', key); clearTimeout(timer); current++; fileToken++; queued = false; processing = null; }; });
</script>
<svelte:window ondragover={(e) => { e.preventDefault(); dragging = true; }} ondragleave={(e) => { if (!e.relatedTarget) dragging = false; }} ondrop={(e) => { e.preventDefault(); dragging = false; if (e.dataTransfer?.files[0]) void load(e.dataTransfer.files[0]); }} />
<div class="app">
<header class="top"><div class="brand"><img src="/logo.svg" width="24" height="24" alt=""/><strong>FabSTEP</strong><span>{t('workspace.tagline')}</span></div><button class="btn" onclick={() => input.click()} title="⌘O"><FileUp size={14}/>{t('workspace.open')}</button><span class="filename">{name || t('workspace.noFile')}</span><div class="spacer"></div><div class="switch" aria-label={t('workspace.language')}>{#each ['fr','en'] as lang}<button aria-pressed={i18n.locale === lang} class:active={i18n.locale === lang} onclick={() => i18n.set(lang as 'fr'|'en')}>{lang.toUpperCase()}</button>{/each}</div><div class="switch" aria-label={t('workspace.theme')}>{#each ['system','light','dark'] as th}{@const Icon = th === 'system' ? Monitor : th === 'light' ? Sun : Moon}<button aria-pressed={theme.choice === th} class:active={theme.choice === th} onclick={() => theme.set(th as 'system'|'light'|'dark')} title={t(`app.themes.${th as 'system'|'light'|'dark'}`)} aria-label={t(`app.themes.${th as 'system'|'light'|'dark'}`)}><Icon size={13}/></button>{/each}</div><button class="btn quiet icon" title={t('workspace.helpTitle')} aria-label={t('workspace.helpTitle')} onclick={() => showHelp = true}><CircleHelp size={16}/></button><button class="btn primary" disabled={!result || busy || result.request_id !== current || !result.bodies.length} title={!result ? t('workspace.allRequired') : t('workspace.export')} onclick={exportStep}><Download size={14}/>{t('workspace.export')}</button></header>
<input class="sr-only" bind:this={input} type="file" tabindex="-1" accept=".stl,.3mf,model/stl,application/sla,model/3mf" onchange={(e) => { const f = e.currentTarget.files?.[0]; if (f) void load(f); e.currentTarget.value = ''; }}/>
<main><aside class="panel left"><Section id="source" title={t('workspace.source')} step={1}><div class="small-label">{t('workspace.file')}</div><button class="file-row" onclick={() => input.click()}><Box size={16}/><span>{name || t('workspace.noFile')}</span><FileUp size={14}/></button><button class="btn" onclick={example}><Box size={14}/>{t('workspace.example')}</button><button class="btn" onclick={cylinderExample}><Box size={14}/>{t('workspace.cylinderExample')}</button><button class="btn" onclick={mixedExample}><Box size={14}/>{t('workspace.mixedExample')}</button><button class="btn" onclick={chamferedExample}><Box size={14}/>{t('workspace.chamferedExample')}</button><button class="btn" onclick={roundedExample}><Box size={14}/>{t('workspace.roundedExample')}</button><button class="btn" onclick={twoCubesExample}><Box size={14}/>{t('workspace.example3mf')}</button><div class="rule"></div>{#if format === '3mf'}<div class="property" title={t('workspace.unitLocked')}><span>{t('workspace.unit3mf')} <span class="hint">ⓘ</span></span><strong>{(preview ? unitText(preview.source.unit) : null) ?? (processing?.phase === 'preview' ? t('workspace.unitReading') : t('workspace.unitUnknown'))}</strong></div><p class="muted">{preview ? (preview.source.unit_origin === 'default' ? t('workspace.unitDefault') : t('workspace.unitDeclared')) : t('workspace.unitLocked')}</p>{:else}<label class="property" title={t('workspace.unitHint')}><span>{t('workspace.unit')} <span class="hint">ⓘ</span></span><select class="input" value={options.input_unit} onchange={(e) => change({ input_unit:e.currentTarget.value as 'mm'|'inch' })}><option value="mm">{t('workspace.mm')} (mm)</option><option value="inch">{t('workspace.inch')} (in)</option></select></label><p class="muted">{t('workspace.unitHint')}</p>{/if}</Section><Section id="conversion" title={t('workspace.settings')} step={2}><label class="property mode-property"><span>{t('workspace.mode')}</span><select class="input" value={options.reconstruction} onchange={(e) => change({ reconstruction:e.currentTarget.value as Options['reconstruction'] })}><option value="planar">{t('workspace.planarMode')}</option><option value="cylinders">{t('workspace.cylinderMode')}</option><option value="primitives">{t('workspace.primitivesMode')}</option><option value="surfaces">{t('workspace.surfacesMode')}</option></select></label><p class="muted">{options.reconstruction === 'surfaces' ? t('workspace.surfacesLimit') : options.reconstruction === 'primitives' ? t('workspace.primitivesLimit') : options.reconstruction === 'cylinders' ? t('workspace.cylinderLimit') : t('workspace.limit')}</p><Disclosure id="advanced" label={t('workspace.advanced')}><label class="property numeric-property" title={t('workspace.weldHint')}><span>{t('workspace.weld')} <span class="hint">ⓘ</span></span><span class="number"><input class="input" type="number" min="0" step="any" value={options.weld_tolerance_mm} aria-invalid={!Number.isFinite(options.weld_tolerance_mm) || options.weld_tolerance_mm <= 0} oninput={(e) => editNumber({ weld_tolerance_mm:e.currentTarget.valueAsNumber })} onblur={finishNumber} onkeydown={finishNumber}/><span>mm</span></span></label><label class="property numeric-property" title={t('workspace.planeHint')}><span>{t('workspace.plane')} <span class="hint">ⓘ</span></span><span class="number"><input class="input" type="number" min="0" step="any" value={options.plane_tolerance_mm} aria-invalid={!Number.isFinite(options.plane_tolerance_mm) || options.plane_tolerance_mm <= 0} oninput={(e) => editNumber({ plane_tolerance_mm:e.currentTarget.valueAsNumber })} onblur={finishNumber} onkeydown={finishNumber}/><span>mm</span></span></label>{#if options.reconstruction !== 'planar' || !validPreferences(options)}<label class="property numeric-property" title={t('workspace.fitToleranceHint')}><span>{t('workspace.fitTolerance')} <span class="hint">ⓘ</span></span><span class="number"><input class="input" type="number" min="0" step="any" value={options.cylinder_fit_tolerance_mm} aria-invalid={!Number.isFinite(options.cylinder_fit_tolerance_mm) || options.cylinder_fit_tolerance_mm <= 0} oninput={(e) => editNumber({ cylinder_fit_tolerance_mm:e.currentTarget.valueAsNumber })} onblur={finishNumber} onkeydown={finishNumber}/><span>mm</span></span></label><label class="property numeric-property" title={t('workspace.maxDeviationHint')}><span>{t('workspace.maxDeviation')} <span class="hint">ⓘ</span></span><span class="number"><input class="input" type="number" min="0" step="any" value={options.max_deviation_mm} aria-invalid={!Number.isFinite(options.max_deviation_mm) || options.max_deviation_mm <= 0} oninput={(e) => editNumber({ max_deviation_mm:e.currentTarget.valueAsNumber })} onblur={finishNumber} onkeydown={finishNumber}/><span>mm</span></span></label><p class="muted">{t('workspace.toleranceExplanation')}</p>{/if}</Disclosure></Section></aside>
<section class="workspace"><div class="workspace-head"><span>{t('workspace.view')}</span><div class="spacer"></div><label class="edge-toggle" title={t('workspace.edges')}><input type="checkbox" bind:checked={showEdges}/>{t('workspace.edges')}</label><button class="btn quiet icon" title={t('workspace.fit')} aria-label={t('workspace.fit')} onclick={() => fitSignal++}><Focus size={16}/></button></div><div class="canvas"><Viewport {bytes} results={selection ? [selection] : result?.bodies ?? []} {preview} {format} {fitSignal} {showEdges} unit={options.input_unit}/>{#if !bytes || (format === '3mf' && !preview)}<div class="empty"><Box size={32}/><strong>{bytes && format === '3mf' ? (!native() ? t('workspace.preview3mf') : processing ? t(`processing.${processing.phase}Title`) : error ? t('workspace.failed') : t('workspace.waiting')) : t('workspace.drop')}</strong><span>{bytes && format === '3mf' ? '' : t('workspace.guidance')}</span></div>{:else}<div class="canvas-label">{t('workspace.preview')}</div><div class="canvas-help">{t('workspace.orbit')}</div>{/if}{#if processing}<ProcessingIndicator phase={processing.phase} startedAt={processing.startedAt}/>{/if}</div></section>
<aside class="panel right"><div class="panel-title">{t('workspace.inspector')}</div><Section id="bodies" title={t('workspace.bodies')}><label class="property"><span>{t('workspace.body')}</span><select class="input" value={selectedId} onchange={(e) => selectedId=e.currentTarget.value}><option value="">{t('workspace.allBodies')}</option>{#each result?.bodies ?? preview?.bodies ?? [] as body, index}<option value={body.id}>{index + 1} · {bodyText(body)}</option>{/each}</select></label><div class="metric"><span>{result ? t('workspace.bodies') : t('workspace.previewCount')}</span><strong>{result?.bodies.length ?? preview?.bodies.length ?? '—'}</strong></div></Section><Section id="mesh" title={t('workspace.mesh')}><div class="metric"><span>{t('workspace.triangles')}</span><strong>{sourceTriangles != null ? fmt(sourceTriangles) : '—'}</strong></div><div class="metric"><span>{t('workspace.vertices')}</span><strong>{sourceVertices != null ? fmt(sourceVertices) : '—'}</strong></div></Section><Section id="solid" title={t('workspace.result')}><div class="metric"><span>{t('workspace.faces')}</span><strong>{metrics ? fmt(metrics.faces) : '—'}</strong></div><div class="metric"><span>{t('workspace.planeFaces')}</span><strong>{metrics ? fmt(metrics.planar_faces) : '—'}</strong></div><div class="metric"><span>{t('workspace.cylinderFaces')}</span><strong>{metrics ? fmt(metrics.cylindrical_faces) : '—'}</strong></div><div class="metric"><span>{t('workspace.conicalFaces')}</span><strong>{metrics ? fmt(metrics.conical_faces) : '—'}</strong></div><div class="metric"><span>{t('workspace.sphericalFaces')}</span><strong>{metrics ? fmt(metrics.spherical_faces) : '—'}</strong></div><div class="metric"><span>{t('workspace.toroidalFaces')}</span><strong>{metrics ? fmt(metrics.toroidal_faces) : '—'}</strong></div>{#if selection?.rounded_recognition}<div class="metric"><span>{t('workspace.toroidalFillets')}</span><strong>{fmt(selection.rounded_recognition.report.toroidal_fillets)}</strong></div>{/if}{#if report}<div class="metric" title={t('workspace.radialResidualHint')}><span>{t('workspace.radialResidual')}</span><strong>{measuredValue(report.max_radial_residual_mm)} mm</strong></div><div class="metric" title={t('workspace.maxDeviationHint')}><span>{t('workspace.deviation')}</span><strong>{precise(report.max_deviation_bound_mm)} mm</strong></div>{/if}<div class="metric"><span>{t('workspace.solids')}</span><strong>{metrics ? fmt(metrics.solids) : '—'}</strong></div><div class="metric"><span>{t('workspace.volume')}</span><strong>{metrics ? `${fmt(metrics.volume_mm3)} mm³` : '—'}</strong></div><div class="metric"><span>{t('workspace.dimensions')}</span><strong>{dims}{metrics ? ' mm' : ''}</strong></div>{#if selection?.fidelity}<Disclosure id="quality" label={t('workspace.quality')}><div class="metric"><span>{t('workspace.sourceToResult')}</span><strong>{precise(selection.fidelity.source_to_result_mm)} mm</strong></div><p class="muted">{fmt(selection.fidelity.source_samples)} {t('workspace.samples')}</p><div class="metric"><span>{t('workspace.resultToSource')}</span><strong>{precise(selection.fidelity.result_to_source_mm)} mm</strong></div><p class="muted">{fmt(selection.fidelity.result_samples)} {t('workspace.samples')}</p><div class="metric"><span>{t('workspace.deflection')}</span><strong>{precise(selection.fidelity.tessellation_deflection_mm)} mm</strong></div><p class="muted">{t('workspace.qualityCaveat')}</p></Disclosure>{/if}{#if result}<Disclosure id="applied-settings" label={t('workspace.appliedSettings')}><div class="metric"><span>{t('workspace.mode')}</span><strong>{result.settings.reconstruction === 'surfaces' ? t('workspace.surfacesMode') : result.settings.reconstruction === 'primitives' ? t('workspace.primitivesMode') : result.settings.reconstruction === 'cylinders' ? t('workspace.cylinderMode') : t('workspace.planarMode')}</strong></div><div class="metric"><span>{t('workspace.weld')}</span><strong>{settingValue(result.settings.weld_tolerance_mm)} mm</strong></div><div class="metric"><span>{t('workspace.plane')}</span><strong>{settingValue(result.settings.plane_tolerance_mm)} mm</strong></div>{#if result.settings.reconstruction !== 'planar'}<div class="metric"><span>{t('workspace.fitTolerance')}</span><strong>{settingValue(result.settings.cylinder_fit_tolerance_mm)} mm</strong></div><div class="metric"><span>{t('workspace.maxDeviation')}</span><strong>{settingValue(result.settings.max_deviation_mm)} mm</strong></div>{/if}</Disclosure>{/if}{#if !result}<p class="muted">{t('workspace.noResult')}</p>{/if}</Section><Section id="diagnostics" title={t('workspace.diagnostics')}>{#if error}<p class="message danger"><TriangleAlert size={14}/><span>{error}{#if recognitionFailed}<small>{t('workspace.strictError')}</small>{/if}</span></p>{/if}{#if bytes && !native()}<p class="message"><TriangleAlert size={14}/><span>{format === '3mf' ? t('workspace.preview3mf') : t('workspace.nativeNote')}</span></p>{/if}{#each result?.diagnostics ?? preview?.diagnostics ?? [] as d}<p class:warning={d.severity === 'warning'} class="message"><TriangleAlert size={14}/><span>{diagnosticText(d.code, d.message)} ({d.count})<small>{d.code}</small></span></p>{/each}{#if selection}{#each selection.analysis.report.diagnostics as d}<p class:warning={d.severity === 'warning'} class="message"><TriangleAlert size={14}/><span>{diagnosticText(d.code, d.message)} ({d.count})<small>{d.code}</small></span></p>{/each}{/if}{#if result && !selection}{#each result.bodies as body, index}{#each body.analysis.report.diagnostics as d}<p class:warning={d.severity === 'warning'} class="message"><TriangleAlert size={14}/><span><small>{index + 1} · {bodyText(body)}</small>{diagnosticText(d.code, d.message, body)} ({d.count})<small>{d.code}</small></span></p>{/each}{/each}{/if}{#if !error && result}<p class="message success"><Layers size={14}/>{t('workspace.ready')}</p>{:else if !error && !result && !preview}<p class="muted">{t('workspace.noResult')}</p>{/if}</Section></aside></main>
{#if showHelp}<Dialog title={t('workspace.helpTitle')} onclose={() => showHelp = false}><h3>{t('workspace.helpAbout')}</h3><p class="help-copy">{t('workspace.helpVersion', {version:packageInfo.version})}</p><h3>{t('workspace.helpUsage')}</h3><p class="help-copy">{t('workspace.helpUnits')}</p><p class="help-copy">{t('workspace.helpLimits')}</p><p class="help-copy">{t('workspace.helpPreview')}</p><h3>{t('workspace.helpShortcuts')}</h3><p class="help-copy">{t('workspace.helpKeys')}</p></Dialog>{/if}<footer><span class:ok={!!result} class:warn={!!processing || (!!bytes && !native())} class:bad={!!error} class="dot"></span><span>{error ? t('workspace.failed') : processing ? t('workspace.pending') : result ? t('workspace.ready') : bytes && !native() ? t('workspace.native') : t('workspace.waiting')}</span><span class="spacer"></span><span>{noteKey ? t(noteKey) : (result ? result.cad.kernel : 'FabSTEP')}</span></footer>{#if dragging}<div class="drop-overlay">{t('workspace.drop')}</div>{/if}</div>
<style>
.help-copy{margin:0}.app{height:100%;display:flex;flex-direction:column}.top{height:42px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;background:var(--bg-chrome);border-top:2px solid var(--identity);border-bottom:1px solid var(--border)}.brand{display:flex;align-items:center;gap:8px;white-space:nowrap;margin-right:12px}.brand strong{font-size:14px}.brand span,.filename{color:var(--text-muted);font-size:11.5px}.filename{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:220px}.spacer{flex:1}.switch{display:flex;padding:2px;gap:2px;background:var(--segment-track);border:1px solid var(--border);border-radius:var(--radius);height:24px}.switch button{border:0;background:none;color:var(--text-muted);padding:0 6px;font-size:10.5px;display:grid;place-items:center}.switch button.active{background:var(--bg-elevated);color:var(--text-primary);border-radius:3px}main{flex:1;min-height:0;display:grid;grid-template-columns:280px minmax(200px,1fr) 280px}.panel{background:var(--bg-panel);overflow:auto}.left{border-right:1px solid var(--border)}.right{border-left:1px solid var(--border)}.panel-title,.workspace-head{height:35px;display:flex;align-items:center;padding:0 12px;border-bottom:1px solid var(--divider);color:var(--text-section);font-size:10.5px;font-weight:600;text-transform:uppercase;letter-spacing:.06em}.workspace{display:flex;flex-direction:column;min-width:0;background:var(--bg-workspace)}.workspace-head{gap:8px}.canvas{position:relative;flex:1;min-height:0}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;pointer-events:none;color:var(--text-muted)}.empty strong{color:var(--text-secondary);font-size:14px;font-weight:500}.canvas-label,.canvas-help{position:absolute;pointer-events:none;color:var(--text-muted);font-size:11px}.canvas-label{left:16px;top:14px}.canvas-help{left:16px;bottom:14px}.edge-toggle{display:flex;align-items:center;gap:5px;text-transform:none;letter-spacing:0;font-weight:400}.edge-toggle input{accent-color:var(--accent)}.small-label{font-size:11px;color:var(--text-muted)}.file-row{display:flex;align-items:center;gap:8px;width:100%;height:32px;padding:0 8px;background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius);text-align:left;color:var(--text-secondary)}.file-row span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text-primary)}.rule{height:1px;background:var(--divider);margin:4px 0}.property,.metric{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:28px;color:var(--text-secondary);font-size:11.5px}.property > span:first-child{white-space:nowrap}.numeric-property > span:first-child{white-space:normal;min-width:0}.property select{width:133px;font-size:11px}.mode-property{align-items:stretch;flex-direction:column;gap:var(--s1)}.mode-property select{width:100%}.hint{color:var(--text-muted)}.number{display:flex;flex:none;align-items:center;gap:6px;color:var(--text-muted)}.number input{width:100px;text-align:right}.number input[aria-invalid="true"]{border-color:var(--danger)}.muted{color:var(--text-muted);font-size:11px;line-height:1.5;margin:0}.metric strong{font-weight:500;color:var(--text-primary);text-align:right;font-variant-numeric:tabular-nums}.message{display:flex;gap:7px;align-items:flex-start;margin:0;color:var(--text-secondary);font-size:11.5px}.message :global(svg){flex:none}.message small{display:block;color:var(--text-muted)}.message.warning{color:var(--warning)}.message.danger{color:var(--danger-text)}.message.success{color:var(--success)}footer{height:24px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;background:var(--bg-chrome);border-top:1px solid var(--border);color:var(--text-muted);font-size:10.5px}.dot{height:7px;width:7px;background:var(--text-muted);border-radius:50%}.dot.ok{background:var(--success)}.dot.warn{background:var(--warning)}.dot.bad{background:var(--danger)}.drop-overlay{position:fixed;inset:8px;display:grid;place-items:center;border:2px dashed var(--accent);background:var(--accent-tint);color:var(--accent-text);font-size:16px;pointer-events:none}@media(max-width:1100px){main{grid-template-columns:250px minmax(200px,1fr) 250px}.brand span{display:none}.filename{max-width:100px}}
</style>
